// Generates TypeScript declaration files from the shared JSON schemas in ../schemas.
// Run with `npm run gen:types`. The generated files are committed so `npm run build`
// works without running this script.
import { compile } from 'json-schema-to-typescript'
import { access, readFile, writeFile, mkdir } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const schemasDir = path.resolve(here, '..', '..', 'schemas')
const outDir = path.resolve(here, '..', 'src', 'protocol')

const jobs = [{ file: 'messages_v2.json', out: 'messages.d.ts', name: 'FragileWebSocketProtocol' }]

const exists = (p) =>
  access(p).then(
    () => true,
    () => false,
  )

await mkdir(outDir, { recursive: true })
for (const job of jobs) {
  const src = path.join(schemasDir, job.file)
  if (!(await exists(src))) {
    // messages_v2.json is written in M1; until then src/protocol/index.ts is hand-written.
    console.log(`skipped ${job.file}: ${path.relative(process.cwd(), src)} does not exist yet`)
    continue
  }
  const raw = await readFile(src, 'utf8')
  const schema = JSON.parse(raw)
  // $id would make the compiler try to resolve refs remotely; strip it.
  delete schema.$id
  const ts = await compile(schema, job.name, {
    bannerComment: `/* eslint-disable */\n/**\n * GENERATED by scripts/gen-types.mjs from schemas/${job.file}.\n * Do not edit by hand. Run \`npm run gen:types\` after changing the schema.\n */`,
    additionalProperties: false,
    strictIndexSignatures: true,
    unreachableDefinitions: true,
    cwd: schemasDir,
    style: { semi: false, singleQuote: true },
  })
  await writeFile(path.join(outDir, job.out), ts, 'utf8')
  console.log(`wrote ${path.relative(process.cwd(), path.join(outDir, job.out))}`)
}
